 hip_probe::Api hip;hip.Check(hip.hipInit(0),"init");hip.Check(hip.hipSetDevice(0),"device");Handle module{},expand{},contract{};hip.Check(hip.hipModuleLoad(&module,argv[2]),"module");hip.Check(hip.hipModuleGetFunction(&expand,module,"c32_ffn_expand_fast"),"expand");hip.Check(hip.hipModuleGetFunction(&contract,module,map3?"c32_ffn_contract_fast_map3":"c32_ffn_contract_fast"),"contract");
