  std::vector<float>input(T*32);for(unsigned i=0;i<input.size();i++)input[i]=pattern==0?fp8(((i*37+11)%96)|((i%3==0)?128:0)):pattern==1?float(int((i*73+19)%2048)-1024)/512.f:float(int((i*17+31)%2048)-1024);
